#!/bin/bash

# Confirms that the checked-in golden files under golden/ are kept up to date
# with the output of foxglove_ts_bundle for test.fbs and its imports. This
# lets reviewers see generator output changes in code review. The checked-in
# files can be regenerated by running
# $ bazel run //tools/foxglove/ts_generator/test:copy_test_foxglove_golden
#
# Usage: compare_generated_files.sh <one_golden_path> <generated_paths...>
# The first arg is used purely to locate the golden/ directory in the
# runfiles tree; the remaining args are every generated file produced by the
# foxglove_ts_bundle.  Files are paired up by basename, and the test fails if
# either set has files the other doesn't.

set -o nounset -o pipefail

if (($# < 2)); then
    echo "Usage: $0 <golden_path> <generated_paths...>" >&2
    exit 2
fi

golden_dir=$(dirname "$1")
shift

declare -A expected_goldens=()
for path in "${golden_dir}"/*; do
    expected_goldens["$(basename "${path}")"]="${path}"
done

status=0
declare -A seen_basenames=()
for generated in "$@"; do
    name=$(basename "${generated}")
    seen_basenames["${name}"]=1
    golden="${expected_goldens[${name}]:-}"
    # Skip generated files that have no checked-in golden. This happens when a
    # transitive dep (e.g. the full @com_github_foxglove_schemas schemas target) produces more
    # outputs than we want to maintain golden files for.
    if [[ -z "${golden}" ]]; then
        continue
    fi
    if ! diff -u "${golden}" "${generated}"; then
        status=1
    fi
done

for name in "${!expected_goldens[@]}"; do
    if [[ -z "${seen_basenames[${name}]:-}" ]]; then
        echo "Golden file has no matching generated output: ${name}" >&2
        status=1
    fi
done

exit "${status}"
